// n8n Error Trigger provides: $json.execution, $json.error, $json.workflow
const item = $input.first().json;

const execution = item.execution ?? {};
const error = item.error ?? {};
const workflow = item.workflow ?? {};

const payload = {
  service: 'n8n',
  project: 'marketforge',
  workflowId: workflow.id ?? 'unknown',
  workflowName: workflow.name ?? 'unknown',
  executionId: execution.id ?? 'unknown',
  executionMode: execution.mode ?? 'unknown',
  retryOf: execution.retryOf ?? null,
  errorMessage: error.message ?? 'Unknown error',
  errorStack: error.stack ?? null,
  lastNodeName: error.node?.name ?? null,
  occurredAt: new Date().toISOString(),
  // Include org_id from execution data if the failing workflow injected it
  orgId: execution.data?.resultData?.runData?.['Validate & Normalise Payload']?.[0]?.data?.main?.[0]?.[0]?.json?._meta?.org_id
       ?? execution.data?.resultData?.runData?.['Validate Payload']?.[0]?.data?.main?.[0]?.[0]?.json?.org_id
       ?? null,
};

const slackText = [
  `*:rotating_light: MarketForge n8n Error*`,
  `*Workflow:* ${payload.workflowName} (${payload.workflowId})`,
  `*Execution:* ${payload.executionId} [${payload.executionMode}]`,
  `*Failed node:* ${payload.lastNodeName ?? 'n/a'}`,
  `*Error:* ${payload.errorMessage}`,
  `*Org:* ${payload.orgId ?? 'n/a'}`,
  `*At:* ${payload.occurredAt}`,
].join('\n');

return [{ json: { ...payload, slackText } }];

// Emit a structured JSON log line; n8n main process will capture it.
// In production this is forwarded to Loki/CloudWatch via log driver.
const e = $input.first().json;
console.error(JSON.stringify({
  level: 'error',
  source: 'n8n-error-handler',
  workflowId: e.workflowId,
  workflowName: e.workflowName,
  executionId: e.executionId,
  orgId: e.orgId,
  errorMessage: e.errorMessage,
  lastNode: e.lastNodeName,
  occurredAt: e.occurredAt,
}));
return $input.all();
